ue; } elseif (version_compare($module['version'], $versionInstalled) >= 0) { $installOk = true; } else { if (version_compare($module['version'], $versionInstalled) === -1) { if ($this->getInput('configModulesCheck', Helper::FILTER_BOOLEAN) === true) { $installOk = true; } else { $this->deleteDir(self::TEMP_DIR . $tempFolder); $zip->close(); return ([ 'success' => false, 'notification' => Helper::translate('La version installée est plus récente') ]); } } } if ($installOk) { $success = $this->copyDir($moduleBaseDir, self::MODULE_DIR . $module['name']); if (is_array($module['dataDirectory'])) { foreach ($module['dataDirectory'] as $src => $dest) { if (!is_dir($moduleBaseDir . $src)) { mkdir($moduleBaseDir . $src); } $success = $success || $this->copyDir($moduleBaseDir . $src, $dest); } } $t = isset($versionInstalled) ? Helper::translate('actualisé') : Helper::translate('installé'); $this->deleteDir(self::TEMP_DIR . $tempFolder); $zip->close(); return ([ 'success' => $success, 'notification' => $success ? sprintf(Helper::translate('Le module %s a été %s'), $module['name'], $t) : Helper::translate('Erreur inconnue, le module n\'est pas installé') ]); } else { $this->deleteDir(self::TEMP_DIR . $tempFolder); $zip->close(); return ([ 'success' => false, 'notification' => Helper::translate('Erreur inconnue, le module n\'est pas installé') ]); } } else { $errorMessages = [ \ZipArchive::ER_EXISTS => "Le fichier existe déjà", \ZipArchive::ER_INCONS => "Archive inconsistante", \ZipArchive::ER_INVAL => "Argument invalide", \ZipArchive::ER_MEMORY => "Erreur de mémoire", \ZipArchive::ER_NOENT => "Fichier non trouvé", \ZipArchive::ER_NOZIP => "Ce n'est pas une archive ZIP", \ZipArchive::ER_OPEN => "Impossible d'ouvrir le fichier", \ZipArchive::ER_READ => "Erreur de lecture", \ZipArchive::ER_SEEK => "Erreur de positionnement" ]; $errorMessage = isset($errorMessages[$zipResult]) ? $errorMessages[$zipResult] : "Erreur inconnue (code: $zipResult)"; return ([ 'success' => false, 'notific